function toast(msg){let t=document.createElement('div');t.className='toast';t.textContent='✓  '+msg;$('#toastRoot').append(t);setTimeout(()=>t.remove(),3000)}function openModal(title,body,onSave,label='Save changes'){currentModal=onSave;$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" id="closeModal">×</button></div>${body}<div class="modal-actions"><button class="secondary" id="cancelModal">Cancel</button><button class="primary" id="saveModal">${label} →</button></div></div></div>`;$('#closeModal').onclick=closeModal;$('#cancelModal').onclick=closeModal;$('#backdrop').addEventListener('click',e=>{if(e.target.id==='backdrop')closeModal()});$('#saveModal').onclick=()=>{const f=$('#modalRoot form');if(f&&!f.reportValidity())return;const data=f?Object.fromEntries(new FormData(f)):{};if(currentModal)currentModal(data);closeModal()}}function closeModal(){$('#modalRoot').innerHTML='';currentModal=null}function fields(items){return `<form class="form-grid">${items.map(x=>`<div class="form-field ${x.full?'full':''}"><label>${x.label}</label>${x.options?`<select name="${x.name}" ${x.required?'required':''}>${x.options.map(o=>`<option>${o}</option>`).join('')}</select>`:`<input name="${x.name}" value="${escape(x.value||'')}" placeholder="${x.placeholder||''}" ${x.required?'required':''} ${x.type==='number'?'type="number"':''}>`}</div>`).join('')}</form>`}
